package provider

import (
	"context"
	"fmt"
	"strings"

	"github.com/hashicorp/terraform-plugin-framework/resource"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema/booldefault"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema/planmodifier"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema/stringplanmodifier"
	"github.com/hashicorp/terraform-plugin-framework/types"
	"github.com/hashicorp/terraform-plugin-log/tflog"
	"github.com/rambhiad/terraform-provider-docker-compose/internal/ssh"
)

var _ resource.Resource = &ProjectResource{}

type ProjectResource struct {
	sshConfig        *SSHConfig
	sshClientFactory func(host string, port int, user string, privateKey string) (ssh.Client, error)
}

type ProjectResourceModel struct {
	Name          types.String `tfsdk:"name"`
	ComposeFile   types.String `tfsdk:"compose_file"`
	Directory     types.String `tfsdk:"directory"`
	RemoveOrphans types.Bool   `tfsdk:"remove_orphans"`
	RemoveVolumes types.Bool   `tfsdk:"remove_volumes"`
	Id            types.String `tfsdk:"id"`
}

func (r *ProjectResource) Metadata(ctx context.Context, req resource.MetadataRequest, resp *resource.MetadataResponse) {
	resp.TypeName = req.ProviderTypeName + "_project"
}

func (r *ProjectResource) Schema(ctx context.Context, req resource.SchemaRequest, resp *resource.SchemaResponse) {
	resp.Schema = schema.Schema{
		Description: "Manages a Docker Compose project on a remote host.",
		Attributes: map[string]schema.Attribute{
			"name": schema.StringAttribute{
				Description: "The name of the Docker Compose project.",
				Required:    true,
				PlanModifiers: []planmodifier.String{
					stringplanmodifier.RequiresReplace(),
				},
			},
			"compose_file": schema.StringAttribute{
				Description: "The content of the docker-compose.yml file.",
				Required:    true,
			},
			"directory": schema.StringAttribute{
				Description: "The directory on the remote host where the compose file will be placed.",
				Required:    true,
				PlanModifiers: []planmodifier.String{
					stringplanmodifier.RequiresReplace(),
				},
			},
			"remove_orphans": schema.BoolAttribute{
				Description: "Remove containers for services not defined in the compose file. Defaults to false.",
				Optional:    true,
				Computed:    true,
				Default:     booldefault.StaticBool(false),
			},
			"remove_volumes": schema.BoolAttribute{
				Description: "Remove volumes when destroying the project. Defaults to false.",
				Optional:    true,
				Computed:    true,
				Default:     booldefault.StaticBool(false),
			},
			"id": schema.StringAttribute{
				Description: "The ID of the project (same as name).",
				Computed:    true,
				PlanModifiers: []planmodifier.String{
					stringplanmodifier.UseStateForUnknown(),
				},
			},
		},
	}
}

func (r *ProjectResource) Configure(ctx context.Context, req resource.ConfigureRequest, resp *resource.ConfigureResponse) {
	if req.ProviderData == nil {
		return
	}

	sshConfig, ok := req.ProviderData.(*SSHConfig)
	if !ok {
		resp.Diagnostics.AddError(
			"Unexpected Resource Configure Type",
			fmt.Sprintf("Expected *SSHConfig, got: %T. Please report this issue to the provider developers.", req.ProviderData),
		)
		return
	}

	r.sshConfig = sshConfig
}

func (r *ProjectResource) Create(ctx context.Context, req resource.CreateRequest, resp *resource.CreateResponse) {
	var data ProjectResourceModel

	resp.Diagnostics.Append(req.Plan.Get(ctx, &data)...)
	if resp.Diagnostics.HasError() {
		return
	}

	client, err := r.sshClientFactory(r.sshConfig.Host, r.sshConfig.Port, r.sshConfig.User, r.sshConfig.PrivateKey)
	if err != nil {
		resp.Diagnostics.AddError("SSH Connection Failed", fmt.Sprintf("Unable to connect to remote host: %s", err))
		return
	}
	defer client.Close()

	// Create directory
	mkdirCmd := fmt.Sprintf("mkdir -p %s", data.Directory.ValueString())
	tflog.Debug(ctx, "Creating directory", map[string]interface{}{"command": mkdirCmd})
	if _, err := client.Run(mkdirCmd); err != nil {
		resp.Diagnostics.AddError("Directory Creation Failed", fmt.Sprintf("Unable to create directory: %s", err))
		return
	}

	// Write compose file
	composeFilePath := fmt.Sprintf("%s/docker-compose.yml", data.Directory.ValueString())
	composeContent := data.ComposeFile.ValueString()
	// Escape single quotes for shell
	escapedContent := strings.ReplaceAll(composeContent, "'", "'\"'\"'")
	writeCmd := fmt.Sprintf("cat > %s << 'EOFCOMPOSE'\n%s\nEOFCOMPOSE", composeFilePath, escapedContent)
	tflog.Debug(ctx, "Writing compose file", map[string]interface{}{"path": composeFilePath})
	if _, err := client.Run(writeCmd); err != nil {
		resp.Diagnostics.AddError("Compose File Write Failed", fmt.Sprintf("Unable to write compose file: %s", err))
		return
	}

	// Run docker compose up
	upCmd := fmt.Sprintf("cd %s && docker compose -p %s up -d", data.Directory.ValueString(), data.Name.ValueString())
	if data.RemoveOrphans.ValueBool() {
		upCmd += " --remove-orphans"
	}
	tflog.Debug(ctx, "Running docker compose up", map[string]interface{}{"command": upCmd})
	if output, err := client.Run(upCmd); err != nil {
		resp.Diagnostics.AddError("Docker Compose Up Failed", fmt.Sprintf("Unable to start containers: %s\nOutput: %s", err, output))
		return
	}

	data.Id = data.Name

	resp.Diagnostics.Append(resp.State.Set(ctx, &data)...)
}

func (r *ProjectResource) Read(ctx context.Context, req resource.ReadRequest, resp *resource.ReadResponse) {
	var data ProjectResourceModel

	resp.Diagnostics.Append(req.State.Get(ctx, &data)...)
	if resp.Diagnostics.HasError() {
		return
	}

	client, err := r.sshClientFactory(r.sshConfig.Host, r.sshConfig.Port, r.sshConfig.User, r.sshConfig.PrivateKey)
	if err != nil {
		resp.Diagnostics.AddError("SSH Connection Failed", fmt.Sprintf("Unable to connect to remote host: %s", err))
		return
	}
	defer client.Close()

	// Check if compose file exists
	composeFilePath := fmt.Sprintf("%s/docker-compose.yml", data.Directory.ValueString())
	checkCmd := fmt.Sprintf("test -f %s && echo exists || echo missing", composeFilePath)
	output, err := client.Run(checkCmd)
	if err != nil {
		resp.Diagnostics.AddError("Read Failed", fmt.Sprintf("Unable to check compose file: %s", err))
		return
	}

	if strings.TrimSpace(output) == "missing" {
		resp.State.RemoveResource(ctx)
		return
	}

	resp.Diagnostics.Append(resp.State.Set(ctx, &data)...)
}

func (r *ProjectResource) Update(ctx context.Context, req resource.UpdateRequest, resp *resource.UpdateResponse) {
	var data ProjectResourceModel

	resp.Diagnostics.Append(req.Plan.Get(ctx, &data)...)
	if resp.Diagnostics.HasError() {
		return
	}

	client, err := r.sshClientFactory(r.sshConfig.Host, r.sshConfig.Port, r.sshConfig.User, r.sshConfig.PrivateKey)
	if err != nil {
		resp.Diagnostics.AddError("SSH Connection Failed", fmt.Sprintf("Unable to connect to remote host: %s", err))
		return
	}
	defer client.Close()

	// Write updated compose file
	composeFilePath := fmt.Sprintf("%s/docker-compose.yml", data.Directory.ValueString())
	composeContent := data.ComposeFile.ValueString()
	escapedContent := strings.ReplaceAll(composeContent, "'", "'\"'\"'")
	writeCmd := fmt.Sprintf("cat > %s << 'EOFCOMPOSE'\n%s\nEOFCOMPOSE", composeFilePath, escapedContent)
	tflog.Debug(ctx, "Writing updated compose file", map[string]interface{}{"path": composeFilePath})
	if _, err := client.Run(writeCmd); err != nil {
		resp.Diagnostics.AddError("Compose File Write Failed", fmt.Sprintf("Unable to write compose file: %s", err))
		return
	}

	// Run docker compose up
	upCmd := fmt.Sprintf("cd %s && docker compose -p %s up -d", data.Directory.ValueString(), data.Name.ValueString())
	if data.RemoveOrphans.ValueBool() {
		upCmd += " --remove-orphans"
	}
	tflog.Debug(ctx, "Running docker compose up", map[string]interface{}{"command": upCmd})
	if output, err := client.Run(upCmd); err != nil {
		resp.Diagnostics.AddError("Docker Compose Up Failed", fmt.Sprintf("Unable to update containers: %s\nOutput: %s", err, output))
		return
	}

	resp.Diagnostics.Append(resp.State.Set(ctx, &data)...)
}

func (r *ProjectResource) Delete(ctx context.Context, req resource.DeleteRequest, resp *resource.DeleteResponse) {
	var data ProjectResourceModel

	resp.Diagnostics.Append(req.State.Get(ctx, &data)...)
	if resp.Diagnostics.HasError() {
		return
	}

	client, err := r.sshClientFactory(r.sshConfig.Host, r.sshConfig.Port, r.sshConfig.User, r.sshConfig.PrivateKey)
	if err != nil {
		resp.Diagnostics.AddError("SSH Connection Failed", fmt.Sprintf("Unable to connect to remote host: %s", err))
		return
	}
	defer client.Close()

	// Run docker compose down
	downCmd := fmt.Sprintf("cd %s && docker compose -p %s down", data.Directory.ValueString(), data.Name.ValueString())
	if data.RemoveVolumes.ValueBool() {
		downCmd += " -v"
	}
	tflog.Debug(ctx, "Running docker compose down", map[string]interface{}{"command": downCmd})
	if output, err := client.Run(downCmd); err != nil {
		resp.Diagnostics.AddError("Docker Compose Down Failed", fmt.Sprintf("Unable to stop containers: %s\nOutput: %s", err, output))
		return
	}

	// Remove compose file
	composeFilePath := fmt.Sprintf("%s/docker-compose.yml", data.Directory.ValueString())
	rmCmd := fmt.Sprintf("rm -f %s", composeFilePath)
	tflog.Debug(ctx, "Removing compose file", map[string]interface{}{"path": composeFilePath})
	if _, err := client.Run(rmCmd); err != nil {
		resp.Diagnostics.AddError("Compose File Removal Failed", fmt.Sprintf("Unable to remove compose file: %s", err))
		return
	}
}

